    class Compare = std::less<ranges::range_value_t<R>>,

    class Allocator = std::allocator<ranges::range_value_t<R>>>

flat_set(std::from_range_t, R &&, Compare = Compare(), Allocator = Allocator())

    -> flat_set<ranges::range_value_t<R>, Compare,

